const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Sakha region (Yakutia) as a polygon
  var sakha = ee.Geometry.Polygon([
    [[105, 50], [165, 50], [165, 75], [105, 75], [105, 50]]
  ]);

  // Define time periods
  var start2015 = '2015-01-01';
  var end2015 = '2015-12-31';
  var start2021 = '2021-01-01';
  var end2021 = '2021-12-31';

  // Load MODIS burned area product
  var burnedArea = ee.ImageCollection('MODIS/006/MCD64A1');

  // Load MODIS land cover for forest classification
  var landcover2015 = ee.Image('MODIS/006/MCD12Q1/2015_01_01').select('LC_Type1');
  var landcover2021 = ee.Image('MODIS/006/MCD12Q1/2021_01_01').select('LC_Type1');

  // Forest classes in IGBP classification: 1-5 (evergreen, deciduous, mixed, closed, open)
  var forestMask2015 = landcover2015.gte(1).and(landcover2015.lte(5));
  var forestMask2021 = landcover2021.gte(1).and(landcover2021.lte(5));

  // Get burned area for 2015 and 2021
  var burned2015 = burnedArea.filterDate(start2015, end2015).filterBounds(sakha);
  var burned2021 = burnedArea.filterDate(start2021, end2021).filterBounds(sakha);

  // Check if collections are empty
  var count2015 = burned2015.size().getInfo();
  var count2021 = burned2021.size().getInfo();

  console.log(`2015 Images: ${count2015}, 2021 Images: ${count2021}`);

  if (count2015 === 0 || count2021 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Create annual composites and mask to forest areas
  var burnedForest2015 = burned2015.max().updateMask(forestMask2015).select('BurnDate');
  var burnedForest2021 = burned2021.max().updateMask(forestMask2021).select('BurnDate');

  // Count burned pixels (BurnDate > 0 indicates burned)
  var burnedPixels2015 = burnedForest2015.gt(0);
  var burnedPixels2021 = burnedForest2021.gt(0);

  // Calculate total burned area in hectares (500m resolution, each pixel = 25ha)
  var reducer = ee.Reducer.sum();
  var scale = 1000;

  var area2015 = burnedPixels2015.reduceRegion({
    reducer: reducer,
    geometry: sakha,
    scale: scale,
    maxPixels: 1e9
  }).get('BurnDate');

  var area2021 = burnedPixels2021.reduceRegion({
    reducer: reducer,
    geometry: sakha,
    scale: scale,
    maxPixels: 1e9
  }).get('BurnDate');

  // Get pixel counts for validation
  var count2015Valid = burnedPixels2015.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: sakha,
    scale: scale,
    maxPixels: 1e9
  }).get('BurnDate');

  var count2021Valid = burnedPixels2021.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: sakha,
    scale: scale,
    maxPixels: 1e9
  }).get('BurnDate');

  var area2015Val = area2015.getInfo();
  var area2021Val = area2021.getInfo();
  var count2015ValidVal = count2015Valid.getInfo();
  var count2021ValidVal = count2021Valid.getInfo();

  console.log(`2015 Burned Pixels: ${area2015Val}, Valid Pixels: ${count2015ValidVal}`);
  console.log(`2021 Burned Pixels: ${area2021Val}, Valid Pixels: ${count2021ValidVal}`);

  // Check for no valid pixels
  if (count2015ValidVal === 0 || count2021ValidVal === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (area2015Val === null || area2021Val === null || 
      isNaN(area2015Val) || isNaN(area2021Val)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare burned areas
  if (area2015Val > area2021Val) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
